package com.momosoftworks.coldsweat.api.event.core.init;

import com.momosoftworks.coldsweat.api.registry.TempModifierRegistry;
import com.momosoftworks.coldsweat.api.temperature.modifier.TempModifier;
import com.momosoftworks.coldsweat.api.util.placement.Placement;
import com.momosoftworks.coldsweat.api.util.Temperature;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.entity.LivingEntity;
import net.minecraftforge.eventbus.api.Event;

import java.util.*;
import java.util.function.Consumer;
import java.util.function.Predicate;

/**
 * Determines the default {@link TempModifier}s that will be applied to an entity upon spawning.<br>
 * This event is fired EVERY TIME the entity joins the world, so make sure to properly check for duplicates.
 */
public class DefaultTempModifiersEvent extends Event
{
    private final Map<Temperature.Trait, List<TempModifier>> modifiers;
    private final LivingEntity entity;

    public DefaultTempModifiersEvent(LivingEntity entity)
    {
        this.entity = entity;
        this.modifiers = new HashMap<>(Temperature.getModifiers(entity));
    }

    public Map<Temperature.Trait, List<TempModifier>> getModifiers()
    {   return modifiers;
    }

    public List<TempModifier> getModifiers(Temperature.Trait trait)
    {   return modifiers.computeIfAbsent(trait, t -> new ArrayList<>());
    }

    public LivingEntity getEntity()
    {   return entity;
    }

    public void addModifier(Temperature.Trait trait, TempModifier modifier)
    {   this.getModifiers(trait).add(modifier);
    }

    public void addModifiers(Temperature.Trait trait, List<TempModifier> modifiers)
    {   this.getModifiers(trait).addAll(modifiers);
    }

    public void addModifier(Temperature.Trait trait, TempModifier modifier, Placement placement)
    {   Temperature.addModifier(this.getModifiers(trait), modifier, placement, null, null);
    }
    public void addModifier(List<Temperature.Trait> traits, TempModifier modifier, Placement placement)
    {
        for (Temperature.Trait trait : traits)
        {   this.addModifier(trait, modifier, placement);
        }
    }

    public void addModifiers(Temperature.Trait trait, List<TempModifier> modifiers, Placement placement)
    {
        for (int i = modifiers.size() - 1; i >= 0; i--)
        {   this.addModifier(trait, modifiers.get(i), placement);
        }
    }

    /**
     * Allows for adding a TempModifier by its registered ID.
     * @param id The ID of the TempModifier to add
     * @param modifierBuilder Called on the TempModifier when it is created, for additional processing
     */
    public void addModifierById(Temperature.Trait trait, ResourceLocation id, Consumer<TempModifier> modifierBuilder, Placement placement)
    {
        Optional<TempModifier> mod = TempModifierRegistry.getValue(id);
        if (mod.isPresent())
        {   modifierBuilder.accept(mod.get());
            addModifier(trait, mod.get(), placement);
        }
    }

    public void addModifierById(List<Temperature.Trait> traits, ResourceLocation id, Consumer<TempModifier> modifierBuilder, Placement placement)
    {
        Optional<TempModifier> mod = TempModifierRegistry.getValue(id);
        if (mod.isPresent())
        {   modifierBuilder.accept(mod.get());
            this.addModifier(traits, mod.get(), placement);
        }
    }

    public void removeModifiers(Temperature.Trait trait, Predicate<TempModifier> predicate)
    {   this.getModifiers(trait).removeIf(predicate);
    }
}

package com.momosoftworks.coldsweat.api.insulation;

import com.mojang.serialization.Codec;
import com.mojang.serialization.codecs.RecordCodecBuilder;
import com.momosoftworks.coldsweat.data.codec.util.ExtraCodecs;
import com.momosoftworks.coldsweat.util.math.CSMath;
import com.momosoftworks.coldsweat.util.serialization.NBTHelper;
import net.minecraft.world.item.ItemStack;

import java.util.ArrayList;
import java.util.List;

public class AdaptiveInsulation extends Insulation
{
    public static final Codec<AdaptiveInsulation> CODEC = RecordCodecBuilder.create(instance -> instance.group(
            ExtraCodecs.DOUBLE.fieldOf("value").forGetter(AdaptiveInsulation::getInsulation),
            ExtraCodecs.DOUBLE.optionalFieldOf("factor", 0d).forGetter(AdaptiveInsulation::getFactor),
            ExtraCodecs.DOUBLE.fieldOf("adapt_speed").forGetter(AdaptiveInsulation::getSpeed)
    ).apply(instance, AdaptiveInsulation::new));

    private final double insulation;
    private final double speed;
    private double factor;

    public AdaptiveInsulation(double insulation, double speed)
    {   this(insulation, 0, speed);
    }

    public AdaptiveInsulation(double insulation, double factor, double speed)
    {   this.insulation = insulation;
        this.factor = factor;
        this.speed = speed;
    }

    public static double calculateChange(AdaptiveInsulation insulation, double worldTemp, double minTemp, double maxTemp)
    {
        double factor = insulation.getFactor();
        double adaptSpeed = insulation.getSpeed();

        double newFactor;
        double tempFactor = CSMath.blend(-1, 1, worldTemp, minTemp, maxTemp);
        if (CSMath.betweenInclusive(tempFactor, -0.5, 0.5))
        {   newFactor = CSMath.shrink(factor, adaptSpeed);
        }
        else
        {
            if (CSMath.sign(factor) != CSMath.sign(tempFactor))
            {   adaptSpeed *= 2;
            }
            newFactor = CSMath.clamp(factor + adaptSpeed * CSMath.sign(tempFactor), -1, 1);
        }
        return newFactor;
    }

    public static double getFactorFromArmor(ItemStack stack)
    {   return NBTHelper.getTagOrEmpty(stack).getDouble("InsulationAdaptation");
    }
    public static void setFactorToArmor(ItemStack stack, double factor)
    {   NBTHelper.getTagOrEmpty(stack).putDouble("InsulationAdaptation", factor);
    }
    public static void readFactorFromArmor(AdaptiveInsulation insulation, ItemStack stack)
    {
        double storedFactor = getFactorFromArmor(stack);
        if (storedFactor != 0)
        {   insulation.setFactor(storedFactor);
        }
    }

    @Override
    public double getValue()
    {   return insulation;
    }

    public double getInsulation()
    {   return insulation;
    }

    public double getFactor()
    {   return factor;
    }

    public void setFactor(double factor)
    {   this.factor = factor;
    }

    public double getSpeed()
    {   return speed;
    }

    @Override
    public double getCold()
    {   return CSMath.blend(insulation * 0.75, 0, factor, -1, 1);
    }

    @Override
    public double getHeat()
    {   return CSMath.blend(0, insulation * 0.75, factor, -1, 1);
    }

    @Override
    public <T extends Insulation> T copy()
    {   return (T) new AdaptiveInsulation(insulation, factor, speed);
    }

    @Override
    public boolean isEmpty()
    {   return insulation == 0;
    }

    @Override
    public List<Insulation> split()
    {
        List<Insulation> insulation = new ArrayList<>();
        for (int i = 0; i < CSMath.ceil(Math.abs(this.insulation) / 2); i++)
        {   double insul = CSMath.minAbs(CSMath.shrink(this.insulation, i * 2), 2 * CSMath.sign(this.insulation));
            insulation.add(new AdaptiveInsulation(insul, factor, speed));
        }
        return insulation;
    }

    @Override
    public String toString()
    {   return "AdaptiveInsulation{" + "insulation=" + insulation + ", factor=" + factor + ", speed=" + speed + '}';
    }

    @Override
    public boolean equals(Object obj)
    {
        if (this == obj) return true;
        return obj instanceof AdaptiveInsulation insul
            && insulation == insul.insulation
            && factor == insul.factor
            && speed == insul.speed;
    }
}

package com.momosoftworks.coldsweat.api.insulation;

import com.mojang.datafixers.util.Either;
import com.mojang.serialization.Codec;
import com.momosoftworks.coldsweat.ColdSweat;
import com.momosoftworks.coldsweat.data.codec.util.ExtraCodecs;
import com.momosoftworks.coldsweat.util.serialization.EnumHelper;
import net.minecraft.util.StringRepresentable;

import javax.annotation.Nullable;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

public abstract class Insulation
{
    public static Codec<Insulation> getCodec()
    {
        return Codec.either(StaticInsulation.CODEC, AdaptiveInsulation.CODEC)
               .xmap(either -> either.map(stat -> stat, adapt -> adapt),
               insul ->
               {
                   if (insul instanceof StaticInsulation)
                   {   return Either.left(((StaticInsulation) insul));
                   }
                   return Either.right(((AdaptiveInsulation) insul));
               });
    }

    /**
     * @return True if this insulation has no value.
     */
    public abstract boolean isEmpty();

    /**
     * If this insulation is bigger than one slot, split it into multiple insulations.
     * @return A list of insulations.
     */
    public abstract List<Insulation> split();

    public abstract double getCold();
    public abstract double getHeat();
    public abstract double getValue();

    public abstract <T extends Insulation> T copy();

    public static List<Insulation> deepCopy(List<Insulation> list)
    {
        List<Insulation> newList = new ArrayList<>();
        for (Insulation insul : list)
        {   newList.add(insul.copy());
        }
        return newList;
    }

    public static List<Insulation> splitList(List<Insulation> pairs)
    {
        List<Insulation> newPairs = new ArrayList<>();
        for (Insulation pair : pairs)
        {   newPairs.addAll(pair.split());
        }
        return newPairs;
    }

    public static List<Insulation> combine(List<Insulation> list1, List<Insulation> list2)
    {
        List<Insulation> combined = new ArrayList<>();
        List<Insulation> remaining = new ArrayList<>(list2);

        for (Insulation ins1 : list1)
        {
            if (ins1 instanceof StaticInsulation staticIns1)
            {
                boolean matched = false;
                for (int i = 0; i < remaining.size(); i++)
                {
                    Insulation ins2 = remaining.get(i);
                    if (ins2 instanceof StaticInsulation staticIns2)
                    {
                        if (combineStaticInsulations(staticIns1, staticIns2, combined))
                        {   remaining.remove(i);
                            matched = true;
                            break;
                        }
                    }
                }
                if (!matched)
                {   combined.add(staticIns1);
                }
            }
            else
            {   combined.add(ins1);
            }
        }
        combined.addAll(remaining);
        combined.removeIf(Insulation::isEmpty);
        return combined;
    }

    private static boolean combineStaticInsulations(StaticInsulation ins1, StaticInsulation ins2, List<Insulation> result)
    {
        double cold1 = ins1.getCold();
        double heat1 = ins1.getHeat();
        double cold2 = ins2.getCold();
        double heat2 = ins2.getHeat();
        // Try to match cold from ins1 with heat from ins2
        if (cold1 > 0 && heat2 > 0)
        {   combineValues(cold1, heat2, result);
            return true;
        }
        // Try to match heat from ins1 with cold from ins2
        if (heat1 > 0 && cold2 > 0)
        {   combineValues(cold2, heat1, result);
            return true;
        }
        // No match found
        return false;
    }

    private static void combineValues(double coldValue, double heatValue, List<Insulation> result)
    {
        if (coldValue == heatValue)
        {   // Equal values, create a neutral insulation
            result.add(new StaticInsulation(coldValue, heatValue));
        }
        else
        {   // Different values, create a neutral insulation with the minimum value
            double minValue = Math.min(coldValue, heatValue);
            result.add(new StaticInsulation(minValue, minValue));

            // Add remaining insulation if any
            if (coldValue > minValue)
            {   result.add(new StaticInsulation(coldValue - minValue, 0));
            }

            if (heatValue > minValue)
            {   result.add(new StaticInsulation(0, heatValue - minValue));
            }
        }
    }

    /**
     * Sort the list of insulation items, starting with cold insulation, then neutral, then heat, then adaptive.<br>
     * This method does not modify the input list
     * @return A sorted list of insulation items.
     */
    public static List<Insulation> sort(List<Insulation> pairs)
    {
        List<Insulation> newPairs = new ArrayList<>(pairs);
        newPairs.sort(Comparator.comparingInt(Insulation::getCompareValue));
        return newPairs;
    }

    public int getCompareValue()
    {
        List<Insulation> subset = this.split();
        if (subset.size() > 1)
        {   return sort(subset).get(0).getCompareValue() - 10;
        }
        else if (this instanceof AdaptiveInsulation insul)
        {   return Math.abs(insul.getInsulation()) >= 2 ? 7 : 8;
        }
        else if (this instanceof StaticInsulation insul)
        {
            double cold = Math.abs(insul.getCold());
            double hot = Math.abs(insul.getHeat());
            if (cold > hot)
            {   return cold >= 2 ? 1 : 2;
            }
            else if (cold == hot)
            {   return cold >= 1 ? 3 : 4;
            }
            else
            {   return hot >= 2 ? 5 : 6;
            }
        }
        return 0;
    }

    public enum Slot implements StringRepresentable
    {
        ITEM("item"),
        CURIO("curio"),
        ARMOR("armor");

        final String name;

        Slot(String name)
        {   this.name = name;
        }

        public static final Codec<Slot> CODEC = ExtraCodecs.enumIgnoreCase(values());

        @Override
        public String getSerializedName()
        {   return name;
        }

        public static Slot byName(String name)
        {   return EnumHelper.byName(values(), name);
        }
    }

    public enum Type implements StringRepresentable
    {
        COLD("cold"),
        HEAT("heat"),
        NEUTRAL("neutral"),
        ADAPTIVE("adaptive");

        final String name;

        Type(String name)
        {   this.name = name;
        }

        public static final Codec<Type> CODEC = ExtraCodecs.enumIgnoreCase(values());

        @Override
        public String getSerializedName()
        {   return name;
        }

        public static Type byName(String name)
        {   return EnumHelper.byName(values(), name);
        }
    }
}

package com.momosoftworks.coldsweat.api.insulation;

import com.mojang.datafixers.util.Pair;
import com.mojang.serialization.Codec;
import com.mojang.serialization.codecs.RecordCodecBuilder;
import com.momosoftworks.coldsweat.data.codec.util.ExtraCodecs;
import com.momosoftworks.coldsweat.util.math.CSMath;
import net.minecraft.nbt.CompoundTag;

import java.util.ArrayList;
import java.util.List;

public class StaticInsulation extends Insulation
{
    public static final Codec<StaticInsulation> CODEC = RecordCodecBuilder.create(instance -> instance.group(
            ExtraCodecs.DOUBLE.fieldOf("cold").forGetter(StaticInsulation::getCold),
            ExtraCodecs.DOUBLE.fieldOf("heat").forGetter(StaticInsulation::getHeat)
    ).apply(instance, StaticInsulation::new));

    private final double cold;
    private final double heat;

    public StaticInsulation(double cold, double heat)
    {   this.cold = cold;
        this.heat = heat;
    }

    public StaticInsulation(Pair<? extends Number, ? extends Number> pair)
    {   this(pair.getFirst().doubleValue(), pair.getSecond().doubleValue());
    }

    @Override
    public double getCold()
    {   return cold;
    }

    @Override
    public double getHeat()
    {   return heat;
    }

    @Override
    public double getValue()
    {   return this.cold + this.heat;
    }

    @Override
    public boolean isEmpty()
    {   return cold == 0 && heat == 0;
    }

    @Override
    public List<Insulation> split()
    {
        List<Insulation> insulation = new ArrayList<>();
        double cold = this.getCold();
        double heat = this.getHeat();
        double neutral = cold > 0 == heat > 0 ? CSMath.minAbs(cold, heat) : 0;
        cold -= neutral;
        heat -= neutral;

        // Cold insulation
        for (int i = 0; i < CSMath.ceil(Math.abs(cold) / 2); i++)
        {   double coldInsul = CSMath.minAbs(CSMath.shrink(cold, i * 2), 2 * CSMath.sign(cold));
            insulation.add(new StaticInsulation(coldInsul, 0d));
        }

        // Neutral insulation
        for (int i = 0; i < CSMath.ceil(Math.abs(neutral)); i++)
        {   double neutralInsul = CSMath.minAbs(CSMath.shrink(neutral, i), CSMath.sign(neutral));
            insulation.add(new StaticInsulation(neutralInsul, neutralInsul));
        }

        // Heat insulation
        for (int i = 0; i < CSMath.ceil(Math.abs(heat) / 2); i++)
        {   double heatInsul = CSMath.minAbs(CSMath.shrink(heat, i * 2),  2 * CSMath.sign(heat));
            insulation.add(new StaticInsulation(0d, heatInsul));
        }
        return insulation;
    }

    @Override
    public <T extends Insulation> T copy()
    {   return (T) new StaticInsulation(cold, heat);
    }

    @Override
    public String toString()
    {   return "Insulation{" + "cold=" + cold + ", heat=" + heat + '}';
    }

    @Override
    public boolean equals(Object obj)
    {
        if (this == obj) return true;
        return obj instanceof StaticInsulation insul
            && cold == insul.cold
            && heat == insul.heat;
    }
}

package com.momosoftworks.coldsweat.api.registry;

import com.google.common.collect.BiMap;
import com.google.common.collect.HashBiMap;
import com.google.common.collect.ImmutableBiMap;
import com.momosoftworks.coldsweat.ColdSweat;
import com.momosoftworks.coldsweat.api.temperature.modifier.TempModifier;
import com.momosoftworks.coldsweat.util.exceptions.RegistryFailureException;
import com.momosoftworks.coldsweat.util.math.CSMath;
import net.minecraft.resources.ResourceLocation;

import javax.annotation.Nullable;
import java.util.Optional;
import java.util.function.Supplier;

public class TempModifierRegistry
{
    static BiMap<ResourceLocation, TempModifierHolder> TEMP_MODIFIERS = HashBiMap.create();

    public static BiMap<ResourceLocation, TempModifierHolder> getEntries()
    {   return ImmutableBiMap.copyOf(TEMP_MODIFIERS);
    }

    public static void register(ResourceLocation id, Supplier<TempModifier> supplier)
    {
        TempModifierHolder holder = new TempModifierHolder(supplier, id);
        if (TEMP_MODIFIERS.containsKey(id) || TEMP_MODIFIERS.values().stream().anyMatch(holder::equals))
        {
            throw ColdSweat.LOGGER.throwing(new RegistryFailureException(id, "TempModifier", String.format("Found duplicate TempModifier entries: %s (%s) %s (%s)", holder.getModifierClass().getName(), id,
                                                                           TEMP_MODIFIERS.get(id).getModifierClass().getName(), id), null));
        }
        TEMP_MODIFIERS.put(id, holder);
    }

    /**
     * Clears the registry of all items. This effectively "un-registers" all TempModifiers.
     */
    public static void flush()
    {
        TEMP_MODIFIERS.clear();
    }

    /**
     * Returns a new instance of the TempModifier with the given ID.<br>
     * If a TempModifier with this ID is not in the registry, this method returns null and logs an error.<br>
     */
    public static Optional<TempModifier> getValue(ResourceLocation id)
    {
        return Optional.ofNullable(TEMP_MODIFIERS.get(id)).map(TempModifierHolder::get);
    }

    public static ResourceLocation getKey(TempModifier modifier)
    {   return CSMath.getIfNotNull(getHolder(modifier), TempModifierHolder::getId, null);
    }

    public static boolean containsKey(ResourceLocation id)
    {   return TEMP_MODIFIERS.containsKey(id);
    }

    @Nullable
    public static TempModifierHolder getHolder(TempModifier modifier)
    {
        for (TempModifierHolder holder : TEMP_MODIFIERS.values())
        {
            if (holder.getModifierClass() == modifier.getClass())
            {   return holder;
            }
        }
        return null;
    }

    public static class TempModifierHolder
    {
        private final Supplier<TempModifier> supplier;
        private final Class<? extends TempModifier> clazz;
        private final ResourceLocation id;

        public TempModifierHolder(Supplier<TempModifier> supplier, ResourceLocation id)
        {   this.supplier = supplier;
            this.clazz = supplier.get().getClass();
            this.id = id;
        }

        public TempModifier get()
        {   return supplier.get();
        }

        public Class<? extends TempModifier> getModifierClass()
        {   return clazz;
        }

        public ResourceLocation getId()
        {   return id;
        }

        @Override
        public boolean equals(Object obj)
        {
            return obj instanceof TempModifierHolder holder && holder.clazz == clazz;
        }

        @Override
        public String toString()
        {   return "TempModifierHolder{" + clazz.getName() + "}";
        }
    }
}

package com.momosoftworks.coldsweat.api.temperature.modifier;

import com.momosoftworks.coldsweat.api.util.Temperature;
import com.momosoftworks.coldsweat.config.ConfigSettings;
import net.minecraft.world.entity.LivingEntity;

import java.util.function.Function;

public class SoulLampTempModifier extends TempModifier
{
    @Override
    public Function<Double, Double> calculate(LivingEntity entity, Temperature.Trait trait)
    {
        double almostMax = Temperature.get(entity, Temperature.Trait.BURNING_POINT) * 0.99;
        return temp ->
        {
            if (temp < almostMax) return temp;

            return Math.max(temp * (1 - ConfigSettings.SOULSPRING_LAMP_STRENGTH.get()), almostMax);
        };
    }
}

package com.momosoftworks.coldsweat.api.temperature.modifier;

import com.mojang.serialization.Codec;
import com.mojang.serialization.codecs.RecordCodecBuilder;
import com.momosoftworks.coldsweat.api.event.common.temperautre.TempModifierEvent;
import com.momosoftworks.coldsweat.api.event.core.registry.TempModifierRegisterEvent;
import com.momosoftworks.coldsweat.api.registry.TempModifierRegistry;
import com.momosoftworks.coldsweat.api.util.Temperature;
import com.momosoftworks.coldsweat.core.init.TempModifierInit;
import com.momosoftworks.coldsweat.util.math.CSMath;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.entity.LivingEntity;
import net.minecraftforge.common.MinecraftForge;

import static com.momosoftworks.coldsweat.api.util.Temperature.Trait;

import java.util.function.Function;
import java.util.function.Supplier;

/**
 * TempModifiers are applied to entities to dynamically change their temperature.<br>
 * For example, biome temperature, time of day, depth, and waterskins are all TempModifiers<br>
 *<br>
 * It is up to you to apply and remove these modifiers manually.<br>
 *<br>
 * TempModifiers must be REGISTERED using {@link TempModifierRegisterEvent}<br>
 * (see {@link TempModifierInit} for an example)<br>
 */
public abstract class TempModifier
{
    private CompoundTag nbt = new CompoundTag();
    private int expireTicks = -1;
    private int ticksExisted = 0;
    private int tickRate = 1;
    private final Double[] lastInput = new Double[Trait.values().length];
    private final Double[] lastOutput = new Double[Trait.values().length];
    private final Function<Double, Double>[] function = new Function[Trait.values().length];
    private boolean changed = false;

    /**
     * Codec for use in complete serialization/deserialization for entities
     */
    public static final Codec<TempModifier> CODEC = RecordCodecBuilder.create(instance -> instance.group(
        ResourceLocation.CODEC.fieldOf("type").forGetter(TempModifierRegistry::getKey),
        CompoundTag.CODEC.optionalFieldOf("nbt", new CompoundTag()).forGetter(TempModifier::getNBT),
        Codec.INT.optionalFieldOf("expire_time", -1).forGetter(TempModifier::getExpireTime),
        Codec.INT.optionalFieldOf("tick_rate", 1).forGetter(TempModifier::getTickRate),
        Codec.INT.optionalFieldOf("ticks_existed", 0).forGetter(TempModifier::getTicksExisted),
        Codec.INT.optionalFieldOf("hash", 0).forGetter(TempModifier::hashCode)
    ).apply(instance, (type, nbt, expire, tickRate, ticksExisted, hash) ->
    {
        TempModifier mod = TempModifierRegistry.getValue(type).orElse(null);
        if (mod == null) return null;
        mod.nbt = nbt;
        mod.expireTicks = expire;
        mod.tickRate = tickRate;
        mod.ticksExisted = ticksExisted;
        return mod;
    }));

    /**
     * Default constructor (REQUIRED for proper registration).<br>
     */
    public TempModifier() {}

    /**
     * TempModifiers can be configured to run {@link TempModifier#calculate(LivingEntity, Temperature.Trait)} at a specified interval.<br>
     * This is useful if the TempModifier is expensive to calculate, and you want to avoid it being called each tick.<br>
     * <br>
     * Every X ticks, the TempModifier's {@code calculate()} function will be called, then stored internally.<br>
     * Every other time {@code update()} is called, the stored value will be returned until X ticks have passed.<br>
     * (new TempModifiers always run {@code calculate()} when they are called for the first time).<br>
     * @param interval the number of ticks between each call to {@code getResult()}.
     * @return this TempModifier instance (allows for in-line building).
     */
    public final <T extends TempModifier> T tickRate(int interval)
    {   tickRate = Math.max(1, interval);
        return (T) this;
    }

    /**
     * Sets the number of ticks this TempModifier will exist before it is automatically removed.
     * @param ticks the number of ticks this modifier will last.
     * @return this TempModifier instance (allows for in-line building).
     */
    public final <T extends TempModifier> T expires(int ticks)
    {
        expireTicks = ticks;
        return (T) this;
    }

    /**
     * Returns a function that changes the input temperature based on the entity and trait this TempModifier is being applied to.<br>
     * Called per trait, since one TempModifier instance can be applied to multiple traits simultaneously.<br><br>
     * <b>ONLY CALLED ON THE SERVER SIDE.</b>
     * @return the new temperature.
     */
    protected abstract Function<Double, Double> calculate(LivingEntity entity, Trait trait);

    /**
     * Called every tick on the temperature modifier.<br>
     * Use this to handle calculations that aren't trait-specific.
     */
    public void tick(LivingEntity entity) {}

    /**
     * Posts this TempModifier's {@link #calculate(LivingEntity, Trait)} to the Forge event bus.<br>
     * Returns the stored value if this TempModifier has a tickRate set, and it is not the right tick.<br>
     * <br>
     * @param temp the Temperature being fed into the {@link #calculate(LivingEntity, Trait)} method.
     * @param entity the entity that is being affected by the modifier.
     */
    public final double update(double temp, LivingEntity entity, Trait trait)
    {
        TempModifierEvent.Calculate.Pre pre = new TempModifierEvent.Calculate.Pre(this, entity, temp, trait);
        MinecraftForge.EVENT_BUS.post(pre);
        if (pre.isCanceled())
        {
            this.setFunction(trait, pre.getFunction());
            return this.apply(trait, pre.getTemperature());
        }

        TempModifierEvent.Calculate.Post post = new TempModifierEvent.Calculate.Post(this, entity, pre.getTemperature(), this.calculate(entity, trait), trait);
        MinecraftForge.EVENT_BUS.post(post);

        this.setFunction(trait, post.getFunction());

        return this.apply(trait, post.getTemperature());
    }

    /**
     * @param temp the Temperature to calculate with
     * @return The result of this TempModifier's unique stored function. Stores the input and output.
     */
    public double apply(Trait trait, double temp)
    {
        this.setLastInput(trait, temp);
        double output = this.getFunction(trait).apply(temp);
        this.setLastOutput(trait, output);
        return output;
    }

    /**
     * Called when this TempModifier is added to the entity.<br>
     */
    public void onAdded(LivingEntity entity, Trait trait) {}

    /**
     * Called when this TempModifier is removed from the entity.<br>
     */
    public void onRemoved(LivingEntity entity, Trait trait) {}

    /**
     * Called when a TempModifier is added to the same trait as this one.<br>
     */
    public void onSiblingAdded(LivingEntity entity, Trait trait, TempModifier sibling) {}

    /**
     * Called when a TempModifier is removed from the same trait as this one.<br>
     */
    public void onSiblingRemoved(LivingEntity entity, Trait trait, TempModifier sibling) {}

    public final int getExpireTime()
    {   return expireTicks;
    }

    public final int getTicksExisted()
    {   return ticksExisted;
    }

    public final int setTicksExisted(int ticks)
    {   return ticksExisted = ticks;
    }

    public final int getTickRate()
    {   return tickRate;
    }

    /**
     * @return The current function that has been calculated for the given trait via {@link #calculate(LivingEntity, Trait)}.<br>
     * Returns a default (no-op) function if one hasn't been calculated for the given trait.
     */
    public final Function<Double, Double> getFunction(Trait trait)
    {
        Function<Double, Double> func = function[trait.ordinal()];
        if (func == null)
        {   this.setFunction(trait, func = temp -> temp);
        }
        return func;
    }

    protected final void setFunction(Trait trait, Function<Double, Double> func)
    {   function[trait.ordinal()] = func;
    }

    /**
     * @return The Temperature this TempModifier was last given
     */
    public final double getLastInput(Trait trait)
    {   return CSMath.orElse(lastInput[trait.ordinal()], 0.0);
    }

    protected final void setLastInput(Trait trait, double temp)
    {   lastInput[trait.ordinal()] = temp;
    }

    /**
     * @return The Temperature this TempModifier's function last returned
     */
    public final double getLastOutput(Trait trait)
    {   return CSMath.orElse(lastOutput[trait.ordinal()], 0.0);
    }

    protected final void setLastOutput(Trait trait, double temp)
    {   lastOutput[trait.ordinal()] = temp;
    }

    public final CompoundTag getNBT()
    {   return nbt;
    }

    public void setNBT(CompoundTag data)
    {   this.nbt = data;
    }

    public void markDirty()
    {   this.changed = true;
    }

    public boolean isDirty()
    {   return this.changed;
    }

    public void markClean()
    {   this.changed = false;
    }

    public ResourceLocation getID()
    {   return TempModifierRegistry.getKey(this);
    }

    @Override
    public boolean equals(Object obj)
    {
        return obj instanceof TempModifier mod
            && this.getClass().equals(mod.getClass())
            && mod.getNBT().equals(this.getNBT());
    }

    @Override
    public String toString()
    {   return this.getID().toString();
    }

    public record Factory(ResourceLocation type, CompoundTag nbt, int expireTime, int tickRate) implements Supplier<TempModifier>
    {
        public static final Codec<Factory> CODEC = RecordCodecBuilder.create(instance -> instance.group(
                ResourceLocation.CODEC.fieldOf("type").forGetter(Factory::type),
                CompoundTag.CODEC.optionalFieldOf("nbt", new CompoundTag()).forGetter(Factory::nbt),
                Codec.INT.optionalFieldOf("expire_time", -1).forGetter(Factory::expireTime),
                Codec.INT.optionalFieldOf("tick_rate", 1).forGetter(Factory::tickRate)
        ).apply(instance, Factory::new));

        @Override
        public TempModifier get()
        {
            TempModifier mod = TempModifierRegistry.getValue(type).orElse(null);
            if (mod == null) return null;
            mod.nbt = nbt.copy();
            mod.expireTicks = expireTime;
            mod.tickRate = tickRate;
            return mod;
        }
    }
}

