            replaceConfigSetting(ItemSettingsConfig.HEARTH_FUELS, "#minecraft:logs_that_burn", list -> list.set(1, 40));
            replaceConfigSetting(ItemSettingsConfig.HEARTH_FUELS, "minecraft:dried_kelp_block", list -> list.set(1, 40));
            replaceConfigSetting(ItemSettingsConfig.HEARTH_FUELS, "minecraft:coal_block", list -> list.set(1, 500));
            replaceConfigSetting(ItemSettingsConfig.HEARTH_FUELS, "minecraft:snow_block", list -> list.set(1, -40));

            replaceConfigSetting(ItemSettingsConfig.BOILER_FUELS, "#minecraft:coals", list -> list.set(1, 55));
            replaceConfigSetting(ItemSettingsConfig.BOILER_FUELS, "#minecraft:logs_that_burn", list -> list.set(1, 40));
            replaceConfigSetting(ItemSettingsConfig.BOILER_FUELS, "minecraft:dried_kelp_block", list -> list.set(1, 40));
            replaceConfigSetting(ItemSettingsConfig.BOILER_FUELS, "minecraft:coal_block", list -> list.set(1, 500));

            replaceConfigSetting(ItemSettingsConfig.ICEBOX_FUELS, "minecraft:snow_block", list -> list.set(1, 40));

            addConfigSetting(WorldSettingsConfig.BLOCK_TEMPERATURES, List.of("create:blaze_burner", 5,  3, "f", 30, "blaze=smouldering", "", 400));
            addConfigSetting(WorldSettingsConfig.BLOCK_TEMPERATURES, List.of("create:blaze_burner", 10, 4, "f", 30, "blaze=fading", "", 400));
            addConfigSetting(WorldSettingsConfig.BLOCK_TEMPERATURES, List.of("create:blaze_burner", 15, 5, "f", 45, "blaze=kindled", "", 400));
            addConfigSetting(WorldSettingsConfig.BLOCK_TEMPERATURES, List.of("create:blaze_burner", 20, 6, "f", 60, "blaze=seething", "", 400));

            addConfigSetting(WorldSettingsConfig.BIOME_TEMPERATURES, List.of("minecraft:plains", 59, 82, "F"));
            replaceConfigSetting(WorldSettingsConfig.BIOME_TEMPERATURES, "minecraft:river", list ->
            {   list.set(1, 59);
                list.set(2, 82);
            });
        }

        /*
         2.4.1
         */
        if (isBehind(configVersion, "2.4.1"))
        {
            addConfigSetting(ItemSettingsConfig.ITEM_TEMPERATURES, List.of("cold_sweat:filled_waterskin",  0.025, "hand,hotbar", "core", "{'Temperature':'0.1:'}", 999, true));
            addConfigSetting(ItemSettingsConfig.ITEM_TEMPERATURES, List.of("cold_sweat:filled_waterskin", -0.025, "hand,hotbar", "core", "{'Temperature':':-0.1'}", 999, true));
            addConfigSetting(ItemSettingsConfig.FOOD_TEMPERATURES, List.of("cold_sweat:filled_waterskin", "{item:Temperature}"));
        }

        /*
         2.4.4
         */
        if (isBehind(configVersion, "2.4.4"))
        {
            // New absolute water temperatures for default biome entries
            Map<String, Pair<Double, Temperature.Units>> defaultWaterTemps = Map.ofEntries(
                    Map.entry("minecraft:badlands",                    Pair.of(90d, Temperature.Units.F)),
                    Map.entry("minecraft:eroded_badlands",             Pair.of(90d, Temperature.Units.F)),
                    Map.entry("minecraft:wooded_badlands",             Pair.of(90d, Temperature.Units.F)),
                    Map.entry("minecraft:swamp",                       Pair.of(78d, Temperature.Units.F)),
                    Map.entry("minecraft:warm_ocean",                  Pair.of(82d, Temperature.Units.F)),
                    Map.entry("biomesoplenty:marsh",                   Pair.of(78d, Temperature.Units.F)),
                    Map.entry("biomesoplenty:wetland",                 Pair.of(74d, Temperature.Units.F)),
                    Map.entry("biomesoplenty:hot_springs",             Pair.of(85d, Temperature.Units.F)),
                    Map.entry("biomeswevegone:bayou",                  Pair.of(67d, Temperature.Units.F)),
                    Map.entry("biomeswevegone:maple_taiga",            Pair.of(5d,  Temperature.Units.C)),
                    Map.entry("biomeswevegone:red_rock_valley",        Pair.of(90d, Temperature.Units.F)),
                    Map.entry("biomeswevegone:rugged_badlands",        Pair.of(90d, Temperature.Units.F)),
                    Map.entry("biomeswevegone:white_mangrove_marshes", Pair.of(78d, Temperature.Units.F)),
                    Map.entry("atmospheric:rocky_dunes",               Pair.of(75d, Temperature.Units.F)),
                    Map.entry("environmental:marsh",                   Pair.of(78d, Temperature.Units.F)),
                    Map.entry("wythers:bayou",                         Pair.of(14d, Temperature.Units.C)),
                    Map.entry("wythers:berry_bog",                     Pair.of(12d, Temperature.Units.C)));

            // Convert biome water temperatures from offsets to absolute values
            List<List<?>> biomeTemps = new ArrayList<>(WorldSettingsConfig.BIOME_TEMPERATURES.get());
            for (int i = 0; i < biomeTemps.size(); i++)
            {
                List<?> entry = biomeTemps.get(i);
                if (entry.size() < 5 || !(entry.get(1) instanceof Number low) || !(entry.get(2) instanceof Number high)
                || !(entry.get(3) instanceof String unitsId) || !(entry.get(4) instanceof Number waterOffset))
                {   continue;
                }
                Temperature.Units units = Temperature.Units.fromID(unitsId);

                List<Object> newEntry = new ArrayList<>(entry);
                // Use the new default value if this is a default biome entry
                Pair<Double, Temperature.Units> defaultWaterTemp = defaultWaterTemps.get(entry.get(0));
                if (defaultWaterTemp != null)
                {
                    newEntry.set(4, Temperature.convert(defaultWaterTemp.getFirst(), defaultWaterTemp.getSecond(), units, true));
                    biomeTemps.set(i, newEntry);
                    continue;
                }
                double lowF = Temperature.convert(low.doubleValue(), units, Temperature.Units.F, true);
                double highF = Temperature.convert(high.doubleValue(), units, Temperature.Units.F, true);
                double offsetF = Temperature.convert(waterOffset.doubleValue(), units, Temperature.Units.F, false);
                double avgF = (lowF + highF) / 2;

                double waterTempF = offsetF > 0
                                    ? 55 + avgF / 4 + offsetF
                                    : 20 + avgF * 0.75 + offsetF;

                double converted = Math.round(Temperature.convert(waterTempF, Temperature.Units.F, units, true));
                newEntry.set(4, converted);
                biomeTemps.set(i, newEntry);
            }
            WorldSettingsConfig.BIOME_TEMPERATURES.set(biomeTemps);
        }

        // Update config version
        MainSettingsConfig.VERSION.set(version);

        MainSettingsConfig.save();
        ItemSettingsConfig.save();
        WorldSettingsConfig.save();
    }

    public static void updateFileNames()
    {
        for (File file : ConfigLoadingHandler.findFilesRecursive(FMLPaths.CONFIGDIR.get().resolve("coldsweat").toFile()))
        {
            if (!file.isFile()) continue;
            switch (file.getName())
            {
                case "world_settings.toml"  -> renameFile(file, "world.toml");
                case "entity_settings.toml" -> renameFile(file, "entity.toml");
                case "item_settings.toml"   -> renameFile(file, "item.toml");
            }
        }
    }

    private static void renameFile(File file, String newName)
    {
        File newFile = file.toPath().resolveSibling(newName).toFile();
        try
        {   Files.move(file, newFile);
        }
        catch (Exception e)
        {   ColdSweat.LOGGER.error("Failed to rename file {} to {}", file, newFile, e);
        }
    }

    private static boolean isBehind(String version, String comparedTo)
    {
        boolean isBehind = compareVersions(version, comparedTo) < 0;
        if (isBehind)
        {   ColdSweat.LOGGER.info("Last launched version {} is less than {}. Updating config settings...", version, comparedTo);
        }
        return isBehind;
    }

    public static int compareVersions(String version, String comparedTo)
    {
        String[] v1Parts = version.split("\\.|\\-");
        String[] v2Parts = comparedTo.split("\\.|\\-");

        int i = 0;
        while (i < v1Parts.length && i < v2Parts.length)
        {
            if (v1Parts[i].matches("\\d+") && v2Parts[i].matches("\\d+"))
            {
                int num1 = Integer.parseInt(v1Parts[i]);
                int num2 = Integer.parseInt(v2Parts[i]);
                if (num1 != num2)
                {   return Integer.compare(num1, num2);
                }
            }
            else
            {
                // If one version is a full release and the other is a beta, the full release is greater
                if (!v1Parts[i].startsWith("b") && v2Parts[i].startsWith("b"))
                {   return 1;
                }
                else if (v1Parts[i].startsWith("b") && !v2Parts[i].startsWith("b"))
                {   return -1;
                }

                int result = comparePreReleaseVersions(v1Parts[i], v2Parts[i]);
                if (result != 0)
                {   return result;
                }
            }
            i++;
        }

        // If all parts are equal so far, but one version has more parts, it's greater
        // unless the shorter one is a full release and the longer one is a beta
        if (v1Parts.length != v2Parts.length)
        {
            if (i == v1Parts.length && i < v2Parts.length && v2Parts[i].startsWith("b"))
            {   return 1;
            }
            else if (i == v2Parts.length && i < v1Parts.length && v1Parts[i].startsWith("b"))
            {   return -1;
            }
        }

        return Integer.compare(v1Parts.length, v2Parts.length);
    }

    private static int comparePreReleaseVersions(String v1, String v2)
    {
        if (v1.startsWith("b") && v2.startsWith("b"))
        {   return compareWithSubVersions(v1.substring(1), v2.substring(1));
        }
        return v1.compareTo(v2);
    }

    private static int compareWithSubVersions(String v1, String v2)
    {
        String[] parts1 = v1.split("(?<=\\d)(?=\\D)|(?<=\\D)(?=\\d)");
        String[] parts2 = v2.split("(?<=\\d)(?=\\D)|(?<=\\D)(?=\\d)");

        int i = 0;
        while (i < parts1.length && i < parts2.length)
        {
            if (parts1[i].matches("\\d+") && parts2[i].matches("\\d+"))
            {
                int num1 = Integer.parseInt(parts1[i]);
                int num2 = Integer.parseInt(parts2[i]);
                if (num1 != num2)
                {   return Integer.compare(num1, num2);
                }
            }
            else
            {
                int result = parts1[i].compareTo(parts2[i]);
                if (result != 0)
                {   return result;
                }
            }
            i++;
        }

        return Integer.compare(parts1.length, parts2.length);
    }

    public static boolean replaceConfigSetting(CSConfigSpec.ConfigValue<List<? extends List<?>>> config, String key,
                                               Consumer<List<Object>> modifier)
    {
        List<List<?>> setting = new ArrayList<>(config.get());
        for (int i = 0; i < setting.size(); i++)
        {
            List<Object> element = new ArrayList<>(setting.get(i));
            if (!element.isEmpty() && element.get(0).equals(key))
            {
                try
                {
                    modifier.accept(element);
                    setting.set(i, element);
                    config.set(setting);
                    return true;
                }
                catch (Exception e)
                {   ColdSweat.LOGGER.error("Failed to update config setting {} for key '{}'", config.getPath(), key, e);
                    return false;
                }
            }
        }
        return false;
    }

    public static void addConfigSetting(CSConfigSpec.ConfigValue<List<? extends List<?>>> config, List<?> newSetting)
    {
        List<List<? extends Object>> setting = new ArrayList<>(config.get());
        if (setting.stream().noneMatch(entry -> !entry.isEmpty() && entry.get(0).equals(newSetting.get(0))))
        {
            config.clearCache();
            setting.add(newSetting);
            config.set(setting);
        }
    }

    public static void removeConfigSetting(CSConfigSpec.ConfigValue<List<? extends List<? extends Object>>> config, String key)
    {
        List<? extends List<? extends Object>> setting = new ArrayList<>(config.get());
        setting.removeIf(entry -> !entry.isEmpty() && entry.get(0).equals(key));
        config.set(setting);
    }
}

