package top.theillusivec4.champions.api.impl;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.concurrent.ConcurrentHashMap;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;
import top.theillusivec4.champions.api.AffixCategory;
import top.theillusivec4.champions.api.IAffix;
import top.theillusivec4.champions.api.IChampionsApi;

public class ChampionsApiImpl implements IChampionsApi {

  private static final ConcurrentHashMap<String, IAffix> affixes = new ConcurrentHashMap<>();
  private static final ConcurrentHashMap<AffixCategory, List<IAffix>> categories =
      new ConcurrentHashMap<>();

  private static ChampionsApiImpl instance = null;

  private static final Logger LOGGER = LogManager.getLogger();

  public static IChampionsApi getInstance() {
    if (instance == null) {
      instance = new ChampionsApiImpl();
      affixes.clear();
      categories.clear();

      for (AffixCategory value : AffixCategory.values()) {
        categories.put(value, new ArrayList<>());
      }
    }
    return instance;
  }

  private ChampionsApiImpl() {
  }

  @Override
  public void registerAffix(IAffix affix) {
    String id = affix.getIdentifier();

    if (affixes.containsKey(id)) {
      LOGGER.error("Skipping affix with duplicate identifier " + id);
      return;
    }
    affixes.put(id, affix);
    categories.get(affix.getCategory()).add(affix);
  }

  @Override
  public void registerAffixes(IAffix... affixes) {

    for (IAffix affix : affixes) {
      this.registerAffix(affix);
    }
  }

  @Override
  public Optional<IAffix> getAffix(String id) {
    return Optional.ofNullable(affixes.get(id));
  }

  @Override
  public List<IAffix> getAffixes() {
    return List.copyOf(affixes.values());
  }

  @Override
  public List<IAffix> getCategory(AffixCategory category) {
    return Collections.unmodifiableList(categories.get(category));
  }

  @Override
  public AffixCategory[] getCategories() {
    return AffixCategory.values();
  }

  @Override
  public Map<AffixCategory, List<IAffix>> getCategoryMap() {
    Map<AffixCategory, List<IAffix>> copy = new HashMap<>();
    categories.forEach((k, v) -> copy.put(k, Collections.unmodifiableList(v)));
    return Collections.unmodifiableMap(copy);
  }
}

package top.theillusivec4.champions.common;

import java.util.List;
import java.util.Optional;
import net.minecraft.Util;
import net.minecraft.network.chat.ChatType;
import net.minecraft.network.chat.TranslatableComponent;
import net.minecraft.server.MinecraftServer;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.util.Tuple;
import net.minecraft.world.effect.MobEffect;
import net.minecraft.world.effect.MobEffectInstance;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.level.Explosion;
import net.minecraft.world.level.block.entity.BeaconBlockEntity;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraftforge.common.util.FakePlayer;
import net.minecraftforge.event.AttachCapabilitiesEvent;
import net.minecraftforge.event.entity.EntityJoinWorldEvent;
import net.minecraftforge.event.entity.living.LivingAttackEvent;
import net.minecraftforge.event.entity.living.LivingDamageEvent;
import net.minecraftforge.event.entity.living.LivingDeathEvent;
import net.minecraftforge.event.entity.living.LivingEvent.LivingUpdateEvent;
import net.minecraftforge.event.entity.living.LivingExperienceDropEvent;
import net.minecraftforge.event.entity.living.LivingHealEvent;
import net.minecraftforge.event.entity.living.LivingHurtEvent;
import net.minecraftforge.event.server.ServerAboutToStartEvent;
import net.minecraftforge.event.server.ServerStoppedEvent;
import net.minecraftforge.event.world.ExplosionEvent;
import net.minecraftforge.eventbus.api.SubscribeEvent;
import top.theillusivec4.champions.api.IChampion;
import top.theillusivec4.champions.common.capability.ChampionCapability;
import top.theillusivec4.champions.common.config.ChampionsConfig;
import top.theillusivec4.champions.common.rank.Rank;
import top.theillusivec4.champions.common.registry.ChampionsRegistry;
import top.theillusivec4.champions.common.stat.ChampionsStats;
import top.theillusivec4.champions.common.util.ChampionBuilder;
import top.theillusivec4.champions.common.util.ChampionHelper;

@SuppressWarnings("unused")
public class ChampionEventsHandler {

  @SubscribeEvent
  public void onLivingXpDrop(LivingExperienceDropEvent evt) {
    LivingEntity livingEntity = evt.getEntityLiving();
    ChampionCapability.getCapability(livingEntity)
      .ifPresent(champion -> champion.getServer().getRank().ifPresent(rank -> {
        int growth = rank.getGrowthFactor();

        if (growth > 0) {
          evt.setDroppedExperience(
            (growth * ChampionsConfig.experienceGrowth * evt.getOriginalExperience() +
              evt.getDroppedExperience()));
        }
      }));
  }

  @SubscribeEvent
  public void onExplosion(ExplosionEvent.Start evt) {
    Explosion explosion = evt.getExplosion();
    Entity entity = explosion.getExploder();

    if (entity != null && !entity.getLevel().isClientSide()) {
      ChampionCapability.getCapability(entity)
        .ifPresent(champion -> champion.getServer().getRank().ifPresent(rank -> {
          int growth = rank.getGrowthFactor();

          if (growth > 0) {
            explosion.radius += ChampionsConfig.explosionGrowth * growth;
          }
        }));
    }
  }

  @SubscribeEvent
  public void onLivingJoinWorld(EntityJoinWorldEvent evt) {
    Entity entity = evt.getEntity();

    if (!entity.getLevel().isClientSide()) {
      ChampionCapability.getCapability(entity).ifPresent(champion -> {
        IChampion.Server serverChampion = champion.getServer();
        Optional<Rank> maybeRank = serverChampion.getRank();

        if (maybeRank.isEmpty()) {
          ChampionBuilder.spawn(champion);
        }
        serverChampion.getAffixes().forEach(affix -> affix.onSpawn(champion));
        serverChampion.getRank().ifPresent(rank -> {
          List<Tuple<MobEffect, Integer>> effects = rank.getEffects();
          effects.forEach(effectPair -> champion.getLivingEntity()
            .addEffect(new MobEffectInstance(effectPair.getA(), 200, effectPair.getB())));
        });
      });
    }
  }

  @SubscribeEvent
  public void onLivingUpdate(LivingUpdateEvent evt) {
    LivingEntity livingEntity = evt.getEntityLiving();

    if (livingEntity.getLevel().isClientSide()) {
      ChampionCapability.getCapability(livingEntity).ifPresent(champion -> {
        IChampion.Client clientChampion = champion.getClient();
        clientChampion.getAffixes().forEach(affix -> affix.onClientUpdate(champion));
        clientChampion.getRank().ifPresent(rank -> {
          if (ChampionsConfig.showParticles && rank.getA() > 0) {
            int color = rank.getB();
            float r = (float) ((color >> 16) & 0xFF) / 255f;
            float g = (float) ((color >> 8) & 0xFF) / 255f;
            float b = (float) ((color) & 0xFF) / 255f;

            livingEntity.getLevel().addParticle(ChampionsRegistry.RANK,
              livingEntity.position().x + (livingEntity.getRandom().nextDouble() - 0.5D) *
                (double) livingEntity.getBbWidth(), livingEntity.position().y +
                livingEntity.getRandom().nextDouble() * livingEntity.getBbHeight(),
              livingEntity.position().z + (livingEntity.getRandom().nextDouble() - 0.5D) *
                (double) livingEntity.getBbWidth(), r, g, b);
          }
        });
      });
    } else if (livingEntity.tickCount % 10 == 0) {
      ChampionCapability.getCapability(livingEntity).ifPresent(champion -> {
        IChampion.Server serverChampion = champion.getServer();
        serverChampion.getAffixes().forEach(affix -> affix.onServerUpdate(champion));
        serverChampion.getRank().ifPresent(rank -> {
          if (livingEntity.tickCount % 4 == 0) {
            List<Tuple<MobEffect, Integer>> effects = rank.getEffects();
            effects.forEach(effectPair -> livingEntity.addEffect(
              new MobEffectInstance(effectPair.getA(), 100, effectPair.getB())));
          }
        });
      });
    }
  }

  @SubscribeEvent
  public void onLivingAttack(LivingAttackEvent evt) {
    LivingEntity livingEntity = evt.getEntityLiving();

    if (livingEntity.getLevel().isClientSide()) {
      return;
    }
    ChampionCapability.getCapability(livingEntity).ifPresent(champion -> {
      IChampion.Server serverChampion = champion.getServer();
      serverChampion.getAffixes().forEach(affix -> {

        if (!affix.onAttacked(champion, evt.getSource(), evt.getAmount())) {
          evt.setCanceled(true);
        }
      });
    });

    if (evt.isCanceled()) {
      return;
    }
    Entity source = evt.getSource().getDirectEntity();
    ChampionCapability.getCapability(source).ifPresent(champion -> {
      IChampion.Server serverChampion = champion.getServer();
      serverChampion.getAffixes().forEach(affix -> {

        if (!affix.onAttack(champion, evt.getEntityLiving(), evt.getSource(), evt.getAmount())) {
          evt.setCanceled(true);
        }
      });
    });
  }

  @SubscribeEvent
  public void onLivingHurt(LivingHurtEvent evt) {
    LivingEntity livingEntity = evt.getEntityLiving();

    if (!livingEntity.getLevel().isClientSide()) {
      float[] amounts = new float[] {evt.getAmount(), evt.getAmount()};
      ChampionCapability.getCapability(livingEntity).ifPresent(champion -> {
        IChampion.Server serverChampion = champion.getServer();
        serverChampion.getAffixes().forEach(
          affix -> amounts[1] = affix.onHurt(champion, evt.getSource(), amounts[0], amounts[1]));
      });
      evt.setAmount(amounts[1]);
    }
  }

  @SubscribeEvent
  public void onLivingDamage(LivingDamageEvent evt) {
    LivingEntity livingEntity = evt.getEntityLiving();

    if (!livingEntity.getLevel().isClientSide()) {
      float[] amounts = new float[] {evt.getAmount(), evt.getAmount()};
      ChampionCapability.getCapability(livingEntity).ifPresent(champion -> {
        IChampion.Server serverChampion = champion.getServer();
        serverChampion.getAffixes().forEach(affix -> amounts[1] = affix
          .onDamage(champion, evt.getSource(), amounts[0], amounts[1]));
      });
      evt.setAmount(amounts[1]);
    }
  }

  @SubscribeEvent
  public void onLivingDeath(LivingDeathEvent evt) {
    LivingEntity livingEntity = evt.getEntityLiving();

    if (livingEntity.getLevel().isClientSide()) {
      return;
    }
    ChampionCapability.getCapability(livingEntity).ifPresent(champion -> {
      IChampion.Server serverChampion = champion.getServer();
      serverChampion.getAffixes().forEach(affix -> {

        if (!affix.onDeath(champion, evt.getSource())) {
          evt.setCanceled(true);
        }
      });
      serverChampion.getRank().ifPresent(rank -> {
        if (!evt.isCanceled()) {
          Entity source = evt.getSource().getEntity();

          if (source instanceof ServerPlayer player && !(source instanceof FakePlayer)) {
            player.awardStat(ChampionsStats.CHAMPION_MOBS_KILLED);
            int messageTier = ChampionsConfig.deathMessageTier;

            if (messageTier > 0 && rank.getTier() >= messageTier) {
              MinecraftServer server = livingEntity.getServer();

              if (server != null) {
                server.getPlayerList().broadcastMessage(
                  new TranslatableComponent("rank.champions.title." + rank.getTier())
                    .append(" ")
                    .append(livingEntity.getCombatTracker().getDeathMessage()),
                  ChatType.SYSTEM, Util.NIL_UUID);
              }
            }
          }
        }
      });
    });
  }

  @SubscribeEvent
  public void onServerStart(ServerAboutToStartEvent evt) {
    ChampionHelper.setServer(evt.getServer());
  }

  @SubscribeEvent
  public void onServerClose(ServerStoppedEvent evt) {
    ChampionHelper.setServer(null);
    ChampionHelper.clearBeacons();
  }

  @SubscribeEvent
  public void onBeaconStart(AttachCapabilitiesEvent<BlockEntity> evt) {
    BlockEntity blockEntity = evt.getObject();

    if (blockEntity instanceof BeaconBlockEntity beaconBlockEntity) {
      ChampionHelper.addBeacon(blockEntity.getBlockPos());
    }
  }

  @SubscribeEvent
  public void onLivingHeal(LivingHealEvent evt) {
    LivingEntity livingEntity = evt.getEntityLiving();

    if (!livingEntity.getLevel().isClientSide()) {
      float[] amounts = new float[] {evt.getAmount(), evt.getAmount()};
      ChampionCapability.getCapability(livingEntity).ifPresent(champion -> {
        IChampion.Server serverChampion = champion.getServer();
        serverChampion.getAffixes()
          .forEach(affix -> amounts[1] = affix.onHeal(champion, amounts[0], amounts[1]));
      });
      evt.setAmount(amounts[1]);
    }
  }
}

package top.theillusivec4.champions.common.affix;

import net.minecraft.nbt.CompoundTag;
import net.minecraft.world.damagesource.DamageSource;
import top.theillusivec4.champions.api.AffixCategory;
import top.theillusivec4.champions.api.IChampion;
import top.theillusivec4.champions.common.affix.core.AffixData;
import top.theillusivec4.champions.common.affix.core.BasicAffix;
import top.theillusivec4.champions.common.config.ChampionsConfig;

public class AdaptableAffix extends BasicAffix {
  public AdaptableAffix() {
    super("adaptable", AffixCategory.DEFENSE);
  }

  @Override
  public float onHurt(IChampion champion, DamageSource source, float amount, float newAmount) {
    String type = source.getMsgId();
    DamageData damageData = AffixData.getData(champion, this.getIdentifier(), DamageData.class);

    if (damageData.name.equalsIgnoreCase(type)) {
      newAmount -= amount * ChampionsConfig.adaptableDamageReductionIncrement * damageData.count;
      damageData.count++;
    } else {
      damageData.name = type;
      damageData.count = 0;
    }
    damageData.saveData();
    return Math.max(amount * (float) (1.0f - ChampionsConfig.adaptableMaxDamageReduction),
        newAmount);
  }

  public static class DamageData extends AffixData {
    String name;
    int count;

    @Override
    public void readFromNBT(CompoundTag tag) {
      name = tag.getString("name");
      count = tag.getInt("count");
    }

    @Override
    public CompoundTag writeToNBT() {
      CompoundTag compound = new CompoundTag();
      compound.putString("name", name);
      compound.putInt("count", count);
      return compound;
    }
  }
}

package top.theillusivec4.champions.common.affix.core;

import java.lang.reflect.InvocationTargetException;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.world.entity.LivingEntity;
import top.theillusivec4.champions.Champions;
import top.theillusivec4.champions.api.IChampion;

public abstract class AffixData {

  private IChampion champion;
  private String identifier;

  protected AffixData() {
  }

  public void readData(IChampion champion, String identifier) {
    this.champion = champion;
    this.identifier = identifier;
    LivingEntity livingEntity = champion.getLivingEntity();
    CompoundTag tag;

    if (!livingEntity.getLevel().isClientSide()) {
      tag = champion.getServer().getData(identifier);
    } else {
      tag = champion.getClient().getData(identifier);
    }
    readFromNBT(tag);
  }

  public abstract void readFromNBT(CompoundTag tag);

  public abstract CompoundTag writeToNBT();

  public void saveData() {
    LivingEntity livingEntity = champion.getLivingEntity();

    if (!livingEntity.getLevel().isClientSide()) {
      champion.getServer().setData(identifier, writeToNBT());
    } else {
      champion.getClient().setData(identifier, writeToNBT());
    }
  }

  public static <T extends AffixData> T getData(IChampion champion, String id, Class<T> clazz) {
    T data = null;

    try {
      data = clazz.getDeclaredConstructor().newInstance();
      data.readData(champion, id);
    } catch (IllegalAccessException | InstantiationException | NoSuchMethodException | InvocationTargetException e) {
      Champions.LOGGER.error("Error reading data from class " + clazz);
    }
    return data;
  }

  public static class BooleanData extends AffixData {

    public boolean mode;

    @Override
    public void readFromNBT(CompoundTag tag) {
      mode = tag.getBoolean("mode");
    }

    @Override
    public CompoundTag writeToNBT() {
      CompoundTag compound = new CompoundTag();
      compound.putBoolean("mode", mode);
      return compound;
    }
  }

  public static class IntegerData extends AffixData {

    public int num;

    @Override
    public void readFromNBT(CompoundTag tag) {
      num = tag.getInt("num");
    }

    @Override
    public CompoundTag writeToNBT() {
      CompoundTag compound = new CompoundTag();
      compound.putInt("num", num);
      return compound;
    }
  }
}

