public class ChampionCapability {

  public static final Capability<IChampion> CHAMPION_CAP =
      CapabilityManager.get(new CapabilityToken<>() {
      });

  public static final ResourceLocation ID = new ResourceLocation(Champions.MODID, "champion");

  private static final String AFFIX_TAG = "affixes";
  private static final String TIER_TAG = "tier";
  private static final String DATA_TAG = "data";
  private static final String ID_TAG = "identifier";

  public static void register() {
    MinecraftForge.EVENT_BUS.register(new CapabilityEventHandler());
    MinecraftForge.EVENT_BUS.register(new ChampionEventsHandler());
  }

  public static Provider createProvider(final LivingEntity livingEntity) {
    return new Provider(livingEntity);
  }

  @Deprecated
  public static LazyOptional<IChampion> getCapability(final LivingEntity entity) {
    return getCapability((Entity) entity);
  }

  public static LazyOptional<IChampion> getCapability(final Entity entity) {

    if (!ChampionHelper.isValidChampion(entity)) {
      return LazyOptional.empty();
    }
    return entity.getCapability(CHAMPION_CAP);
  }

  public static class Champion implements IChampion {

    private final LivingEntity champion;
    private final Client client;
    private final Server server;

    private Champion(final LivingEntity livingEntity) {
      this.champion = livingEntity;
      this.client = new Client();
      this.server = new Server();
    }

    @Override
    public Client getClient() {
      return this.client;
    }

    @Override
    public Server getServer() {
      return this.server;
    }

    @Nonnull
    @Override
    public LivingEntity getLivingEntity() {
      return this.champion;
    }

    public static class Server implements IChampion.Server {

      private Rank rank = null;
      private List<IAffix> affixes = new ArrayList<>();
      private final Map<String, CompoundTag> data = new HashMap<>();

      @Override
      public Optional<Rank> getRank() {
        return Optional.ofNullable(rank);
      }

      @Override
      public void setRank(Rank rank) {
        this.rank = rank;
      }

      @Override
      public List<IAffix> getAffixes() {
        return Collections.unmodifiableList(this.affixes);
      }

      @Override
      public void setAffixes(List<IAffix> affixes) {
        this.affixes = affixes;
      }

      @Override
      public void setData(String identifier, CompoundTag data) {
        this.data.put(identifier, data);
      }

      @Override
      public CompoundTag getData(String identifier) {
        return this.data.getOrDefault(identifier, new CompoundTag());
      }
    }

    public static class Client implements IChampion.Client {

      private Tuple<Integer, Integer> rank = null;
      private final List<IAffix> affixes = new ArrayList<>();
      private final Map<String, IAffix> idToAffix = new HashMap<>();
      private final Map<String, CompoundTag> data = new HashMap<>();

      @Override
      public Optional<Tuple<Integer, Integer>> getRank() {
        return Optional.ofNullable(rank);
      }

      @Override
      public void setRank(Tuple<Integer, Integer> rank) {
        this.rank = rank;
      }

      @Override
      public List<IAffix> getAffixes() {
        return Collections.unmodifiableList(this.affixes);
      }

      @Override
      public void setAffixes(Set<String> affixes) {
        this.affixes.clear();

        for (String affix : affixes) {
          Champions.API.getAffix(affix).ifPresent(val -> {
            this.affixes.add(val);
            this.idToAffix.put(val.getIdentifier(), val);
          });
        }
      }

      @Override
      public Optional<IAffix> getAffix(String id) {
        return Optional.ofNullable(this.idToAffix.get(id));
      }

      @Override
      public void setData(String identifier, CompoundTag data) {
        this.data.put(identifier, data);
      }

      @Override
      public CompoundTag getData(String identifier) {
        return this.data.getOrDefault(identifier, new CompoundTag());
      }
    }
  }

  public static class Provider implements ICapabilitySerializable<Tag> {

    final LazyOptional<IChampion> optional;
    final IChampion data;

    Provider(final LivingEntity livingEntity) {
      this.data = new Champion(livingEntity);
      this.optional = LazyOptional.of(() -> data);
    }

    @NotNull
    @Override
    public <T> LazyOptional<T> getCapability(@NotNull final Capability<T> cap,
                                             @Nullable final Direction side) {
      return cap == CHAMPION_CAP ? optional.cast() : LazyOptional.empty();
    }

    @Override
    public Tag serializeNBT() {
      CompoundTag compoundNBT = new CompoundTag();
      IChampion.Server champion = data.getServer();
      champion.getRank().ifPresent(rank -> compoundNBT.putInt(TIER_TAG, rank.getTier()));
      List<IAffix> affixes = champion.getAffixes();
      ListTag list = new ListTag();
      affixes.forEach(affix -> {
        CompoundTag tag = new CompoundTag();
        String id = affix.getIdentifier();
        tag.putString(ID_TAG, id);
        tag.put(DATA_TAG, champion.getData(id));
        list.add(tag);
      });
      compoundNBT.put(AFFIX_TAG, list);
      return compoundNBT;
    }

    @Override
    public void deserializeNBT(final Tag nbt) {
      CompoundTag compoundNBT = (CompoundTag) nbt;
      IChampion.Server champion = data.getServer();

      if (compoundNBT.contains(TIER_TAG)) {
        int tier = compoundNBT.getInt(TIER_TAG);
        champion.setRank(RankManager.getRank(tier));
      }

      if (compoundNBT.contains(AFFIX_TAG)) {
        ListTag list = compoundNBT.getList(AFFIX_TAG, CompoundTag.TAG_COMPOUND);
        List<IAffix> affixes = new ArrayList<>();

        for (int i = 0; i < list.size(); i++) {
          CompoundTag tag = list.getCompound(i);
          String id = tag.getString(ID_TAG);
          Champions.API.getAffix(id).ifPresent(affix -> {
            affixes.add(affix);

            if (tag.hasUUID(DATA_TAG)) {
              champion.setData(id, tag.getCompound(DATA_TAG));
            }
          });
        }
        champion.setAffixes(affixes);
      }
    }
  }
}

package top.theillusivec4.champions.common.rank;

import com.google.common.collect.ImmutableSortedMap;
import java.util.ArrayList;
import java.util.List;
import java.util.TreeMap;
import javax.annotation.Nonnull;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.util.Tuple;
import net.minecraft.world.effect.MobEffect;
import net.minecraftforge.registries.ForgeRegistries;
import top.theillusivec4.champions.Champions;
import top.theillusivec4.champions.api.IAffix;
import top.theillusivec4.champions.common.config.ChampionsConfig;
import top.theillusivec4.champions.common.config.RanksConfig.RankConfig;

public class RankManager {

  private static final TreeMap<Integer, Rank> RANKS = new TreeMap<>();

  private static final Rank EMPTY_RANK = new Rank();

  public static ImmutableSortedMap<Integer, Rank> getRanks() {
    return ImmutableSortedMap.copyOf(RANKS);
  }

  @Nonnull
  public static Rank getRank(int tier) {
    Rank rank = RANKS.get(tier);

    if (rank != null) {
      return rank;
    } else if (RANKS.isEmpty()) {
      return EMPTY_RANK;
    } else {
      return RANKS.firstEntry().getValue();
    }
  }

  public static Rank getLowestRank() {
    return RANKS.isEmpty() ? EMPTY_RANK : RANKS.firstEntry().getValue();
  }

  public static Rank getHighestRank() {
    return RANKS.isEmpty() ? EMPTY_RANK : RANKS.lastEntry().getValue();
  }

  public static void buildRanks() {
    List<RankConfig> ranks = ChampionsConfig.ranks;

    if (ranks == null) {
      return;
    }
    ranks.forEach(rank -> {
      try {
        Rank newRank = getRankFromConfig(rank);
        RANKS.put(newRank.getTier(), newRank);
      } catch (NullPointerException e) {
        Champions.LOGGER.error("Null rank found with tier {} while building rank, skipping...", rank.tier);
      } catch (IllegalArgumentException e) {
        Champions.LOGGER.error("Invalid attribute found while building rank, skipping...");
      }
    });
  }

  private static Rank getRankFromConfig(RankConfig rank) throws IllegalArgumentException {
    if (rank.tier == null || rank.numAffixes == null || rank.chance == null
        || rank.defaultColor == null || rank.growthFactor == null || rank.effects == null
        || rank.presetAffixes == null) {
      throw new IllegalArgumentException("Missing rank attribute");
    }
    int tier;

    if (rank.tier < 0) {
      throw new IllegalArgumentException("Negative tier");
    } else {
      tier = rank.tier;
    }
    int numAffixes;

    if (rank.numAffixes < 0) {
      throw new IllegalArgumentException("Negative number of affixes");
    } else {
      numAffixes = rank.numAffixes;
    }
    double chance;

    if (rank.chance < 0) {
      throw new IllegalArgumentException("Non-positive chance");
    } else {
      chance = rank.chance;
    }
    int defaultColor = rank.defaultColor;

    int growthFactor;

    if (rank.growthFactor < 0) {
      throw new IllegalArgumentException("Negative growth factor");
    } else {
      growthFactor = rank.growthFactor;
    }
    List<Tuple<MobEffect, Integer>> effects = new ArrayList<>();

    rank.effects.forEach(effect -> {
      String[] parsed = effect.split(";");
      MobEffect found = ForgeRegistries.MOB_EFFECTS.getValue(new ResourceLocation(parsed[0]));

      if (found != null) {
        int amplifier = 0;

        if (parsed.length > 1) {
          try {
            amplifier = Integer.parseInt(parsed[1]);
          } catch (NumberFormatException e) {
            Champions.LOGGER
                .error("Found invalid amplifier value for effect, setting to default 1");
          }
        }
        effects.add(new Tuple<>(found, amplifier));
      }
    });

    List<IAffix> presetAffixes = new ArrayList<>();
    rank.presetAffixes
        .forEach(affix -> Champions.API.getAffix(affix).ifPresent(presetAffixes::add));
    return new Rank(tier, numAffixes, growthFactor, (float) chance, defaultColor, effects,
        presetAffixes);
  }
}

package top.theillusivec4.champions.common.util;

import com.google.common.collect.ImmutableSortedMap;
import java.util.ArrayList;
import java.util.HashMap;
